package com.example.soundguardian;
import com.soundguardian.core.SoundContract; import com.soundguardian.core.AppConfig; import com.soundguardian.core.EventEngine; import com.soundguardian.core.YamnetClassifier;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.Manifest;import android.media.*;import android.os.*;import androidx.core.app.NotificationCompat;import java.util.*;import java.util.concurrent.*;
public class ListenService extends Service {
 public static final String ACTION="soundguardian.update"; private AudioRecord record; private ExecutorService exec; private YamnetClassifier model; private AppConfig config; private EventEngine events; private volatile boolean running;
 public int onStartCommand(Intent i,int f,int id){if(!running){running=true;startForeground(7,notification());exec=Executors.newSingleThreadExecutor();exec.execute(this::loop);}return START_NOT_STICKY;}
 private Notification notification(){NotificationChannel c=new NotificationChannel("listen","声音守护",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(c);return new NotificationCompat.Builder(this,"listen").setContentTitle("居家声音守护").setContentText("正在本地监听").setSmallIcon(android.R.drawable.ic_btn_speak_now).build();}
 private void loop(){try{if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)throw new SecurityException("未授予麦克风权限");model=new YamnetClassifier(this);config=new AppConfig(this);events=new EventEngine(config.rules);int n=AudioRecord.getMinBufferSize(SoundContract.SAMPLE_RATE,16,2);record=new AudioRecord(MediaRecorder.AudioSource.MIC,SoundContract.SAMPLE_RATE,16,2,Math.max(n,32000));record.startRecording();short[] b=new short[SoundContract.HOP_SAMPLES];float[] x=new float[SoundContract.INPUT_SAMPLES];int filled=0;while(running){int read=record.read(b,0,b.length);if(read<=0)continue;for(int k=0;k<read;k++){x[filled++]=b[k]/32768f;if(filled==x.length){long inferenceStart=SystemClock.elapsedRealtimeNanos();float[] scores=model.classify(x);float inferenceMs=(SystemClock.elapsedRealtimeNanos()-inferenceStart)/1000000f;events.update(scores,System.currentTimeMillis());Intent v=new Intent(ACTION);v.setPackage(getPackageName());v.putExtra("score",scores);v.putExtra("inference_ms",inferenceMs);v.putParcelableArrayListExtra("events",eventRecords());v.putExtra("labels",config.labels);v.putExtra("current",events.current());v.putExtra("history",events.recent());v.putExtra("level",level(b,read));v.putExtra("dbfs",dbfs(b,read));sendBroadcast(v);System.arraycopy(x,SoundContract.HOP_SAMPLES,x,0,SoundContract.OVERLAP_SAMPLES);filled=SoundContract.OVERLAP_SAMPLES;}}}}catch(Exception e){Intent v=new Intent(ACTION);v.setPackage(getPackageName());v.putExtra("error",e.toString());sendBroadcast(v);}}
 private ArrayList<Bundle> eventRecords(){ArrayList<Bundle> rows=new ArrayList<>();for(EventEngine.Event e:events.history){Bundle row=new Bundle();row.putString("id",e.rule.index+":"+e.start);row.putString("name",e.rule.zh);row.putLong("start",e.start);row.putLong("end",e.end);row.putBoolean("active",e.active);rows.add(row);}return rows;}
 private float dbfs(short[] b,int n){double sum=0;for(int i=0;i<n;i++){double v=b[i]/32768.0;sum+=v*v;}return (float)Math.max(-96,20*Math.log10(Math.max(1e-9,Math.sqrt(sum/n))));}
 private int level(short[] b,int n){long s=0;for(int i=0;i<n;i++)s+=(long)b[i]*b[i];return (int)Math.min(100,Math.sqrt((double)s/n)/327.68);}
 public void onDestroy(){running=false;if(events!=null)events.stop(System.currentTimeMillis());if(record!=null){record.stop();record.release();}if(exec!=null)exec.shutdownNow();if(model!=null)model.close();super.onDestroy();} public android.os.IBinder onBind(Intent i){return null;}
}

